import{_ as a,a as t}from"./chunks/fixedwing_dtrim.CBgAydAV.js";import{_ as i,o as r,c as o,al as n}from"./chunks/framework.7vp1BMOE.js";const g=JSON.parse('{"title":"Посібник з обрізання фіксованого крила","description":"","frontmatter":{},"headers":[],"relativePath":"uk/config_fw/trimming_guide_fixedwing.md","filePath":"uk/config_fw/trimming_guide_fixedwing.md"}'),d={name:"uk/config_fw/trimming_guide_fixedwing.md"};function c(l,e,h,s,_,f){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="посібник-з-обрізання-фіксованого-крила" tabindex="-1">Посібник з обрізання фіксованого крила <a class="header-anchor" href="#посібник-з-обрізання-фіксованого-крила" aria-label="Permalink to &quot;Посібник з обрізання фіксованого крила&quot;">​</a></h1><p>Стрічки використовуються для калібрування керуючих поверхонь в умовах обрізання (відносна швидкість повітря, густина повітря, кут атаки, конфігурація літака тощо). Правильно обрізаний літак, що летить в умовах обтримування, буде утримувати свою позицію без потреби в будь-яких керувальних сигналах від пілота або стабілізуючого комп&#39;ютера.</p><p>General aviation, commercial and large unmanned planes trim their control surfaces using <a href="https://en.wikipedia.org/wiki/Trim_tab" target="_blank" rel="noreferrer">trim tabs</a> while small UAVs simply add an offset to the actuator of the control surface.</p><p>The <a href="#basic-trimming">Basic trimming</a> section explains the purpose of each trim parameter and how to find the correct value. The <a href="#advanced-trimming">Advanced Trimming</a> section introduces parameters that can be set to automatically adjust the trims based on the measured airspeed and flap position.</p><h2 id="основна-обрізка" tabindex="-1">Основна обрізка <a class="header-anchor" href="#основна-обрізка" aria-label="Permalink to &quot;Основна обрізка&quot;">​</a></h2><p>Існують кілька параметрів, які оператор може бажати використовувати для належного обрізання літака з фіксованим крилом. Огляд цих параметрів та їх використання показано нижче:</p><ul><li><a href="./../advanced_config/parameter_reference#RC1_TRIM">RCx_TRIM</a> applies trim to the signal received from the RC transmitter. These parameters are set automatically during <a href="./../config/radio">RC calibration</a>.</li><li><a href="./../advanced_config/parameter_reference#CA_SV_CS0_TRIM">CA_SV_CSx_TRIM</a> applies trim to a control surfaces channel. Ці засоби використовуються для точного вирівнювання керуючих поверхонь до типових кутів перед польотом.</li><li><a href="./../advanced_config/parameter_reference#FW_PSP_OFF">FW_PSP_OFF</a> is the pitch angle at which your aircraft flies level at trim airspeed. See <a href="#level-flight-pitch">Level-Flight Pitch</a> for how PX4 defines and uses it.</li><li><a href="./../advanced_config/parameter_reference#FW_AIRSPD_TRIM">FW_AIRSPD_TRIM</a> is used by the rate controllers to scale their output depending on the measured airspeed. See <a href="./../flight_stack/controller_diagrams#airspeed-scaling">Airspeed Scaling</a> for more details.</li><li><a href="./../advanced_config/parameter_reference#TRIM_ROLL">TRIM_ROLL</a>, <a href="./../advanced_config/parameter_reference#TRIM_PITCH">TRIM_PITCH</a> and <a href="./../advanced_config/parameter_reference#TRIM_YAW">TRIM_YAW</a> apply trim to the control signals <em>before</em> mixing. For example, if you have two servos for the elevator, <code>TRIM_PITCH</code> applies trim to both of them. Ці використовуються, коли ваші керуючі поверхні вирівняні, але літак піднімається/кочується/повертається вгору/вниз/ліворуч/праворуч під час ручного (не стабілізованого) польоту або якщо сигнал керування має постійний зсув під час стабілізованого польоту.</li></ul><p>Правильний порядок встановлення вищезазначених параметрів:</p><ol><li>Trim the servos by physically adjusting the linkages lengths if possible and fine tune by trimming the PWM channels (use <code>PWM_MAIN/AUX_TRIMx</code>) on the bench to properly set the control surfaces to their theoretical position.</li><li>Fly in stabilized mode at cruise speed and set <code>FW_PSP_OFF</code> to the pitch angle that the airplane needs to fly at in order to keep constant altitude during wing-leveled flight. If you are using an airspeed sensor, also set the correct cruise airspeed (<code>FW_AIRSPD_TRIM</code>).</li><li>Look at the actuator controls in the log file (upload it to <a href="https://logs.px4.io" target="_blank" rel="noreferrer">Flight Review</a> and check the <em>Actuator Controls</em> plot for example) and set the pitch trim (<code>TRIM_PITCH</code>). Встановіть це значення на середнє зміщення сигналу тану під час польоту на рівні крила.</li></ol><p>Крок 3 можна виконати перед кроком 2, якщо ви не хочете дивитися на журнал або якщо вам зручно керувати літаком вручну. You can then trim your remote (with the trim switches) and report the values to <code>TRIM_PITCH</code> (and remove the trims from your transmitter) or update <code>TRIM_PITCH</code> directly during flight via telemetry and QGC.</p><h2 id="level-flight-pitch" tabindex="-1">Level-Flight Pitch <a class="header-anchor" href="#level-flight-pitch" aria-label="Permalink to &quot;Level-Flight Pitch&quot;">​</a></h2><p>PX4 measures the fixed-wing pitch angle θ between the body x-axis and the horizon. The body frame is fixed to the vehicle: x points forward through the nose, y along the right wing and z down. Its orientation follows the mounting of the flight controller (see <a href="./../config/flight_controller_orientation">Flight Controller Orientation</a>), not the wing chord. For tailsitters, the fixed-wing body frame is the multicopter body frame rotated by 90° in pitch.</p><p><img src="'+a+'" alt="Side view of a fixed-wing aircraft pitched up: the body x-axis points forward, z down and y along the right wing out of the page; the pitch angle θ is the angle between the body x-axis and the horizon, and in level flight at trim airspeed it equals FW_PSP_OFF"></p><p><a href="./../advanced_config/parameter_reference#FW_PSP_OFF">FW_PSP_OFF</a> is θ in level flight at trim airspeed (<a href="./../advanced_config/parameter_reference#FW_AIRSPD_TRIM">FW_AIRSPD_TRIM</a>). In level flight the velocity is horizontal, so this is also the angle of attack measured from the body x-axis. It differs from the angle of attack of the wing by the angle between the wing chord and the body x-axis.</p><p>Pitch setpoints and pitch limits in PX4 are absolute pitch angles θ, and <code>FW_PSP_OFF</code> is not added to them. This applies for example to <a href="./../advanced_config/parameter_reference#FW_P_LIM_MIN">FW_P_LIM_MIN</a>, <a href="./../advanced_config/parameter_reference#FW_P_LIM_MAX">FW_P_LIM_MAX</a>, <a href="./../advanced_config/parameter_reference#FW_TKO_PITCH_MIN">FW_TKO_PITCH_MIN</a>, <a href="./../advanced_config/parameter_reference#FW_LND_FL_PMIN">FW_LND_FL_PMIN</a>, <a href="./../advanced_config/parameter_reference#FW_LND_FL_PMAX">FW_LND_FL_PMAX</a> and <a href="./../advanced_config/parameter_reference#RWTO_PSP">RWTO_PSP</a>.</p><p><code>FW_PSP_OFF</code> itself is used in these places:</p><ul><li>The altitude and airspeed controller (TECS) uses <code>FW_PSP_OFF</code> as the pitch at zero climb angle: its pitch setpoint is <code>FW_PSP_OFF</code> plus the commanded climb angle plus an integrator correction. The logged TECS pitch setpoint (<code>tecs_status.pitch_sp_rad</code>) is absolute, while the logged pitch integrator (<code>tecs_status.pitch_integ</code>) is a correction added to it rather than a pitch angle.</li><li>In <a href="./../flight_modes_fw/stabilized">Stabilized mode</a>, the centred pitch stick commands <code>FW_PSP_OFF</code>.</li><li>During the front transition, standard VTOLs ramp their pitch setpoint to <code>FW_PSP_OFF</code>, and tailsitters end their pitch-down rotation at it.</li><li>The first principle check of the <a href="./../advanced_config/airspeed_validation">airspeed validation</a> considers the vehicle to be pitching down when θ is below <code>FW_PSP_OFF</code>.</li></ul><h2 id="розширении-обрізка" tabindex="-1">Розширений обрізка <a class="header-anchor" href="#розширении-обрізка" aria-label="Permalink to &quot;Розширений обрізка&quot;">​</a></h2><p>Оскільки знижувальний момент крену, викликаний асиметричним повітряним профілем, збільшується разом із швидкістю повітря та коли висунуті закрилки, літак потребує повторного налаштування відповідно до поточно виміряної швидкості повітря та положення закрилків. Для цієї мети можна визначити білінійну криву функції швидкості повітря та функції інкременту тримання кута за допомогою параметрів стану закріплення (див. рисунок нижче):</p><ul><li><a href="./../advanced_config/parameter_reference#FW_DTRIM_R_VMIN">FW_DTRIM_[R/P/Y]_[VMIN/VMAX]</a> are the roll/pitch/yaw trim value added to <code>TRIM_ROLL/PITCH/YAW</code> at min/max airspeed (defined by <a href="./../advanced_config/parameter_reference#FW_AIRSPD_MIN">FW_AIRSPD_MIN</a> and <a href="./../advanced_config/parameter_reference#FW_AIRSPD_MAX">FW_AIRSPD_MAX</a>).</li><li><a href="./../advanced_config/parameter_reference#CA_SV_CS0_FLAP">CA_SV_CSx_FLAP</a> and <a href="./../advanced_config/parameter_reference#CA_SV_CS0_SPOIL">CA_SV_CSx_SPOIL</a> are the trimming values that are applied to these control surfaces if the flaps or the spoilers are fully deployed, respectively.</li></ul><p><img src="'+t+'" alt="Dtrim Curve"></p><p>Ідеально симетрична конструкція фюзеляжу вимагала б лише інкрементів відкалібрування крена, але оскільки реальний фюзеляж ніколи не є ідеально симетричним, інкременти відкалібрування крена та курсу іноді також потрібні.</p>',22)])])}const u=i(d,[["render",c]]);export{g as __pageData,u as default};
